declare(strict_types=1);require_once dirname($_SERVER['DOCUMENT_ROOT']).'/backyard_private/app/bootstrap.php';$u=requireUser();$state=(string)($_GET['state']??'');$expected=(string)($_SESSION['oauth_state']??'');unset($_SESSION['oauth_state']);if($expected===''||!hash_equals($expected,$state)||!isset($_GET['code'])){http_response_code(400);exit('Strava-Anmeldung abgebrochen oder ungültig.');}
try{$r=httpJson('POST','https://www.strava.com/oauth/token',['client_id'=>cfg('STRAVA_CLIENT_ID'),'client_secret'=>cfg('STRAVA_CLIENT_SECRET'),'code'=>(string)$_GET['code'],'grant_type'=>'authorization_code']);$id=(int)$r['athlete']['id'];$s=db()->prepare('SELECT user_id FROM athletes WHERE athlete_id=?');$s->execute([$id]);$other=$s->fetchColumn();if($other!==false&&(int)$other!==(int)$u['id'])throw new RuntimeException('Dieses Strava-Konto ist bereits einem anderen Benutzer zugeordnet.');$s=db()->prepare('INSERT INTO athletes (user_id,athlete_id,access_token,refresh_token,expires_at) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE athlete_id=VALUES(athlete_id),access_token=VALUES(access_token),refresh_token=VALUES(refresh_token),expires_at=VALUES(expires_at),last_full_sync=NULL');$s->execute([$u['id'],$id,enc((string)$r['access_token']),enc((string)$r['refresh_token']),(int)$r['expires_at']]);redirect('dashboard.php?connected=1');}catch(Throwable $e){http_response_code(400);echo 'Strava-Verbindung fehlgeschlagen: '.h($e->getMessage());}
